#include <atomic>
#include <iostream>
#include <thread>

int main() {
    std::atomic_flag ready{};
    std::jthread worker([&] {
        ready.test_and_set();
        std::atomic_flag_notify_one(&ready);
        std::atomic_flag_notify_all(&ready);
    });
    std::atomic_flag_wait(&ready, false);
    std::atomic_flag_wait_explicit(&ready, false, std::memory_order_seq_cst);
    worker.join();
    std::cout << std::boolalpha << ready.test() << "\n";
}
